import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api"; // تأكد من مسار ملف axios الخاص بك

const ROLES = [
  {id:"student",label:"Student",emoji:"🎓",desc:"Find & apply to internships",sel:"border-[#2E7DF7] bg-blue-50"},
  {id:"company",label:"Company",emoji:"🏢",desc:"Post offers & hire interns",sel:"border-slate-700 bg-slate-100"},
  {id:"admin",  label:"Admin",  emoji:"🏛️",desc:"Manage & validate placements",sel:"border-[#9b4a42] bg-red-50"},
];

export default function Register() {
  const [step, setStep]       = useState(1);
  const [role, setRole]       = useState(null);
  const [showPass, setShowPass] = useState(false);
  const [form, setForm]       = useState({fullname:"", email:"", password:""});
  const [loading, setLoading]   = useState(false);
  const navigate = useNavigate();

  const upd = (k,v) => setForm(f=>({...f,[k]:v}));

  // التحقق من البيانات (Validation)
  const validName  = form.fullname.trim().split(" ").filter(Boolean).length >= 2;
  const validEmail = role === "student"
    ? /^[^\s@]+@[^\s@]+\.(dz|edu\.dz|edu)$/i.test(form.email)
    : form.email.includes("@") && form.email.includes(".");
  const validPass  = form.password.length >= 8;
  const canSubmit  = validName && validEmail && validPass && role;

  // --- دالة الإرسال لـ Django ---
  const handleRegister = async (e) => {
    e.preventDefault();
    if (!canSubmit) return;

    setLoading(true);
    try {
      const payload = {
        username: form.email, // نستخدم الإيميل كاسم مستخدم لسهولة الدخول
        email: form.email,
        fullname: form.fullname,
        password: form.password,
        role: role
      };

      await api.post('register/', payload);
      setStep(3); // الانتقال لخطوة النجاح
    } catch (error) {
      console.error("Registration error:", error.response?.data);
      const msg = error.response?.data?.username 
        ? "هذا البريد الإلكتروني مسجل بالفعل." 
        : "حدث خطأ أثناء التسجيل، يرجى المحاولة لاحقاً.";
      alert(msg);
    } finally {
      setLoading(false);
    }
  };

  const passStrength = form.password.length === 0 ? 0 : form.password.length < 6 ? 1 : form.password.length < 10 ? 2 : 4;
  const strengthLabel = ["","ضعيفة","متوسطة","جيدة","قوية"][passStrength];
  const strengthColor = ["","bg-red-500","bg-yellow-500","bg-blue-500","bg-green-500"][passStrength];

  const btnCls = role === "company" ? "bg-slate-900" : role === "admin" ? "bg-red-900" : "bg-blue-600";

  return (
    <div className="min-h-screen bg-[#fdf9f5] flex overflow-hidden">
      
      {/* القسم الأيسر - معلومات المنصة */}
      <div className="hidden lg:flex lg:w-[44%] bg-slate-900 flex-col justify-between relative p-10">
        <div className="relative">
          <Link to="/" className="font-bold text-2xl text-white">Stag<span className="text-blue-500">.</span>io</Link>
        </div>
        <div className="relative">
          <h2 className="text-white text-4xl font-extrabold leading-tight mb-6">
            ابدأ رحلة <br/><span className="text-blue-400">تربصك المهني</span> اليوم.
          </h2>
          <div className="space-y-6">
            {["اختر دورك", "املأ بياناتك", "ابدأ البحث"].map((t, i) => (
              <div key={i} className="flex items-center gap-4 text-white opacity-80">
                <div className="w-8 h-8 rounded-full border border-white/20 flex items-center justify-center text-sm">{i+1}</div>
                <span className="text-sm font-medium">{t}</span>
              </div>
            ))}
          </div>
        </div>
        <p className="text-slate-500 text-xs">© 2025–2026 · Stag.io Platform</p>
      </div>

      {/* القسم الأيمن - واجهة التسجيل */}
      <div className="flex-1 flex flex-col justify-center items-center px-6 py-12 overflow-y-auto">
        <div className="w-full max-w-lg"></div>
        {/* الخطوة 1: اختيار الدور */}
          {step === 1 && (
            <div className="w-full animate-in fade-in duration-500">
              <h2 className="text-3xl font-bold text-slate-900 mb-2">إنشاء حساب جديد</h2>
              <p className="text-slate-500 mb-8">لديك حساب بالفعل؟ <Link to="/login" className="text-blue-600 font-bold">دخول →</Link></p>
              
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-8">
                {ROLES.map(r => (
                  <div key={r.id} onClick={() => setRole(r.id)}
                    className={`cursor-pointer border-2 rounded-2xl p-4 text-center transition-all ${role===r.id ? r.sel : "border-slate-100 bg-white hover:border-slate-200"}`}>
                    <div className="text-3xl mb-2">{r.emoji}</div>
                    <div className="font-bold text-slate-800 text-sm">{r.label}</div>
                    <p className="text-[10px] text-slate-400 mt-1">{r.desc}</p>
                  </div>
                ))}
              </div>

              <button disabled={!role} onClick={() => setStep(2)}
                className={`w-full text-white font-bold py-3 rounded-xl transition-all ${role ? "bg-slate-900 shadow-lg" : "bg-slate-200 cursor-not-allowed"}`}>
                {role ?` الاستمرار كـ ${role} ←` : "اختر نوع الحساب"}
              </button>
            </div>
          )}

          {/* الخطوة 2: إدخال البيانات */}
          {step === 2 && (
            <div className="w-full animate-in slide-in-from-right duration-500">
              <button onClick={() => setStep(1)} className="text-sm text-slate-400 mb-6 font-medium hover:text-slate-600">← العودة</button>
              <h2 className="text-3xl font-bold text-slate-900 mb-2">بياناتك الشخصية</h2>
              <p className="text-slate-500 mb-8">يرجى إدخال معلومات دقيقة للتواصل.</p>

              <form onSubmit={handleRegister} className="space-y-5">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">الاسم الكامل</label>
                  <input
                    required
                    className="w-full p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="الاسم واللقب"
                    value={form.fullname}
                    onChange={e => upd("fullname", e.target.value)}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">البريد الإلكتروني</label>
                  <input
                    required
                    type="email"
                    className="w-full p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="example@domain.com"
                    value={form.email}
                    onChange={e => upd("email", e.target.value)}
                  />
                  {role === "student" && <p className="text-[10px] text-slate-400 mt-1">يفضل استخدام البريد الجامعي (edu.dz)</p>}
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">كلمة المرور</label>
                  <div className="relative">
                    <input
                      required
                      type={showPass ? "text" : "password"}
                      className="w-full p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                      placeholder="8 رموز على الأقل"
                      value={form.password}
                      onChange={e => upd("password", e.target.value)}
                    />
                    <button type="button" onClick={() => setShowPass(!showPass)} className="absolute right-3 top-3 text-slate-400">{showPass ? "🙈" : "👁️"}</button>
                    </div>
                  {form.password && (
                    <div className="flex gap-1 mt-2">
                      {[1,2,3,4].map(i => <div key={i} className={`h-1 flex-1 rounded-full ${passStrength>=i ? strengthColor : "bg-slate-200"}`}/>)}
                    </div>
                  )}
                </div>

                <button 
                  type="submit"
                  disabled={!canSubmit || loading}
                  className={`w-full text-white font-bold py-3 rounded-xl transition-all ${canSubmit && !loading ? btnCls : "bg-slate-300 cursor-not-allowed"}`}
                >
                  {loading ? "جاري إنشاء الحساب..." : "إنشاء حسابي الآن ←"}
                </button>
              </form>
            </div>
          )}

          {/* الخطوة 3: النجاح */}
          {step === 3 && (
            <div className="text-center animate-in zoom-in duration-500">
              <div className="text-6xl mb-6">🎉</div>
              <h2 className="text-3xl font-bold text-slate-900 mb-4">تم إنشاء الحساب بنجاح!</h2>
              <p className="text-slate-500 mb-8">يمكنك الآن تسجيل الدخول والبدء في استخدام المنصة.</p>
              <Link to="/login" className="block w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg">توجه لتسجيل الدخول</Link>
            </div>
          )}
        </div>
      </div>
    
  );
}
